comparison_rows={'review-swift-with-ai': [('Compiler diagnostic', 'Build with the same scheme and SDK', 'A successful build'), ('Heuristic finding', 'Inspect the surrounding isolation and ownership', 'A justified patch or documented false positive'), ('Behavior concern', 'Reproduce the user action', 'A passing behavioral test')], 'verify-swiftui-simulator': [('Persistence', 'Terminate and relaunch', 'Previously saved item remains'), ('Search', 'Clear a nonmatching query', 'Original list returns'), ('Accessibility', 'Inspect labels and larger text', 'Readable layout and meaningful controls')], 'choose-ai-client': [('Local coding client', 'Local stdio MCP server', 'Node.js; Xcode for simulator work'), ('Browser conversation', 'Supported remote connection or portable guidance', 'Account policy and secure hosting'), ('Connection test', 'Tool discovery', 'Does not establish model task success')], 'claude-swift-review': [('Before editing', 'Read the finding in context', 'Location and reason'), ('After patching', 'Review the diff', 'Only intended changes'), ('Before completion', 'Build and test', 'Commands, outcomes, remaining gaps')], 'chatgpt-codex-ios': [('Planning', 'Screens and acceptance criteria', 'A plan, not a running app'), ('Implementation', 'Connected local environment', 'Inspectable source changes'), ('Verification', 'Build, tests and simulator', 'Recorded evidence')], 'gemini-cli-ios': [('Tools absent', 'Check configuration and executable', 'Connection problem'), ('Build fails', 'Inspect scheme and Xcode diagnostic', 'Project problem'), ('Wrong behavior', 'Reproduce acceptance criterion', 'Implementation problem')], 'muse-verification': [('Tool discovery', 'Recorded', 'Server communication'), ('Stop hook', 'Recorded with echo provider', 'Hook invocation'), ('Model-driven app build', 'Not verified by this record', 'Requires a separate real task')], 'swiftui-state-review': [('Empty library', 'Fresh test store', 'Explain how to add an item'), ('Empty search', 'Nonmatching query', 'Clear search without losing data'), ('Error', 'Controlled failure', 'Preserve context and offer recovery')], 'generate-asset-catalog': [('Light and dark', 'Explicit token values', 'Inspect both appearances'), ('High contrast', 'Two additional explicit values', 'Measure against real backgrounds'), ('Existing catalog', 'Generate a sibling output', 'Review and merge intentionally')]}
def enrich(content,slug):
 headings=[]
 def heading(m):
  text=re.sub('<[^>]+>','',m[1]); anchor=re.sub('[^a-z0-9]+','-',text.lower()).strip('-')
  headings.append((anchor,text));return '<h2 id="'+anchor+'">'+m[1]+'</h2>'
 if slug in comparison_rows:
  content+='<h2>Decision checkpoints</h2><table><thead><tr><th>Situation</th><th>Action or status</th><th>Evidence or boundary</th></tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+html.escape(cell)+'</td>' for cell in row)+'</tr>' for row in comparison_rows[slug])+'</tbody></table>'
 content=re.sub(r'<h2>(.*?)</h2>',heading,content)
 toc='<aside class="article-toc" aria-label="Table of contents"><strong>On this page</strong><ol>'+''.join('<li><a href="#'+a+'">'+t+'</a></li>' for a,t in headings)+'</ol></aside>'
 steps=next((x[4] for x in new_posts if x[0]==slug),[t for _,t in headings[:4]])
 flow='<section class="workflow" aria-label="Article workflow"><p class="eyebrow">The workflow</p><ol>'+''.join('<li><span>'+str(i+1).zfill(2)+'</span>'+html.escape(t)+'</li>' for i,t in enumerate(steps))+'</ol></section>'
 return toc+flow+content
cards=[]
for slug,title,desc,img,caption,content in posts:
 img='assets/blog/'+slug+'.jpg'
